class Solution:
    def minSubarraySort(self, nums: List[int], k: int) -> List[int]:
        res = []
        for st in range(len(nums) - k + 1):
            w = sorted(nums[st:st + k])
            lo = 0
            while lo < k and nums[st + lo] == w[lo]:
                lo += 1
            if lo == k:
                res.append(0)
                continue
            hi = k - 1
            while nums[st + hi] == w[hi]:
                hi -= 1
            res.append(hi - lo + 1)
        return res

