class Solution {
public:
    vector<int> minSubarraySort(vector<int>& nums, int k) {
        vector<int> res;
        vector<int> w(k);
        for (int st = 0; st + k <= (int)nums.size(); st++) {
            copy(nums.begin() + st, nums.begin() + st + k, w.begin());
            sort(w.begin(), w.end());
            int lo = 0;
            while (lo < k && nums[st + lo] == w[lo]) lo++;
            if (lo == k) { res.push_back(0); continue; }
            int hi = k - 1;
            while (nums[st + hi] == w[hi]) hi--;
            res.push_back(hi - lo + 1);
        }
        return res;
    }
};

