        int n = nums.length;
        int[] res = new int[n - k + 1];
        int[] w = new int[k];
        for (int st = 0; st + k <= n; st++) {
            System.arraycopy(nums, st, w, 0, k);
            Arrays.sort(w);
            int lo = 0;
            while (lo < k && nums[st + lo] == w[lo]) lo++;
            if (lo == k) { res[st] = 0; continue; }
            int hi = k - 1;
            while (nums[st + hi] == w[hi]) hi--;
            res[st] = hi - lo + 1;
        }
        return res;
    }
}

