class Solution:
    def minSubarraySort(self, nums: List[int], k: int) -> List[int]:
        res = []
        n = len(nums)
        for st in range(n - k + 1):
            en = st + k - 1
            i = -1
            for idx in range(st, en):
                if nums[idx] > nums[idx + 1]:
                    i = idx
                    break
            if i == -1:
                res.append(0)
                continue
            j = -1
            for idx in range(en - 1, st - 1, -1):
                if nums[idx] > nums[idx + 1]:
                    j = idx + 1
                    break
            mn, mx = min(nums[i:j + 1]), max(nums[i:j + 1])
            l = i
            while l > st and nums[l - 1] > mn:
                l -= 1
            r = j
            while r < en and nums[r + 1] < mx:
                r += 1
            res.append(r - l + 1)
        return res

