class Solution {
    public int[] minSubarraySort(int[] nums, int k) {
        int n = nums.length;
        int[] res = new int[n - k + 1];
        for (int st = 0; st + k <= n; st++) {
            int en = st + k - 1, i = -1;
            for (int idx = st; idx < en; idx++)
                if (nums[idx] > nums[idx + 1]) { i = idx; break; }
            if (i == -1) { res[st] = 0; continue; }
            int j = -1;
            for (int idx = en - 1; idx >= st; idx--)
                if (nums[idx] > nums[idx + 1]) { j = idx + 1; break; }
            int mn = Integer.MAX_VALUE, mx = Integer.MIN_VALUE;
            for (int idx = i; idx <= j; idx++) { mn = Math.min(mn, nums[idx]); mx = Math.max(mx, nums[idx]); }
            int l = i, r = j;
            while (l > st && nums[l - 1] > mn) l--;
            while (r < en && nums[r + 1] < mx) r++;
            res[st] = r - l + 1;
        }
        return res;
    }
}

